import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { Manifest } from 'release-please';
import { assertReleaseTarget, checksumInstallers, installerNames } from './lib.mjs';

const root = fileURLToPath(new URL('../../', import.meta.url));
const source = 'a'.repeat(40);
const previous = 'b'.repeat(40);
const quiet = { debug() {}, info() {}, warn() {}, error() {} };

async function candidates(commits) {
  const github = {
    repository: { owner: 'doudar', repo: 'Skarix', defaultBranch: 'main' },
    async getFileJson(file, ref) {
      return JSON.parse((await this.getFileContentsOnBranch(file, ref)).parsedContent);
    },
    async getFileContentsOnBranch(file, ref) {
      assert.equal(ref, source, 'all version and configuration reads must use the tested SHA');
      const parsedContent = readFileSync(path.join(root, file), 'utf8');
      return { parsedContent, content: Buffer.from(parsedContent).toString('base64') };
    },
    async *releaseIterator() {
      const version = JSON.parse(readFileSync(path.join(root, '.release-please-manifest.json')))[
        '.'
      ];
      yield { tagName: `v${version}`, sha: previous, notes: 'Previous release' };
    },
    async *mergeCommitIterator(ref) {
      assert.equal(ref, source, 'history must use the tested SHA');
      yield* commits.map((commit) => ({ sha: source, ...commit }));
      yield { sha: previous, message: 'chore(main): previous release', files: [] };
    },
  };
  const manifest = await Manifest.fromManifest(github, source, undefined, undefined, {
    separatePullRequests: true,
    logger: quiet,
  });
  return manifest.buildPullRequests();
}

test('Release Please prepares matching version files and public notes without a release PR', async () => {
  const releases = await candidates([
    { message: 'fix: keep saved projects available', files: ['src/App.tsx'] },
  ]);
  assert.equal(releases.length, 1);
  const candidate = releases[0];
  const current = JSON.parse(readFileSync(path.join(root, 'package.json'))).version;
  const [major, minor, patch] = current.split('.').map(Number);
  const version = `${major}.${minor}.${patch + 1}`;
  assert.equal(candidate.version.toString(), version);
  assert.match(candidate.body.releaseData[0].notes, /keep saved projects available/);
  for (const file of ['package.json', 'package-lock.json', '.release-please-manifest.json']) {
    const update = candidate.updates.find((entry) => entry.path === file);
    assert.ok(update, `${file} is generated by Release Please`);
    const next = JSON.parse(
      update.updater.updateContent(readFileSync(path.join(root, file), 'utf8')),
    );
    assert.equal(file.startsWith('.') ? next['.'] : next.version, version);
    if (next.packages) assert.equal(next.packages[''].version, version);
  }
});

test('website-only and documentation-only commits do not release the app', async () => {
  for (const commit of [
    { message: 'feat: website change', files: ['site/build.mjs'] },
    { message: 'fix: website screenshot', files: ['docs/assets/screenshot.png'] },
    { message: 'docs: clarify installation', files: ['docs/INSTALLATION.md'] },
    { message: 'chore(site): update website', files: ['site/build.mjs', 'README.md'] },
  ])
    assert.equal((await candidates([commit])).length, 0);
});

test('mixed app and website changes still release the application', async () => {
  const releases = await candidates([
    { message: 'feat: offer more cutting options', files: ['src/App.tsx', 'site/build.mjs'] },
  ]);
  assert.equal(releases.length, 1);
  assert.match(releases[0].body.releaseData[0].notes, /offer more cutting options/);
});

test('release assets require all three matching, nonempty installers and verified SHA-256 hashes', (t) => {
  const directory = mkdtempSync(path.join(os.tmpdir(), 'skarix-assets-'));
  t.after(() => rmSync(directory, { recursive: true, force: true }));
  const names = installerNames('1.2.3');
  assert.throws(() => checksumInstallers(directory, '1.2.3'), /exactly the three/);
  for (const name of names) writeFileSync(path.join(directory, name), name);
  const checksums = checksumInstallers(directory, '1.2.3');
  for (const name of names)
    assert.ok(checksums.includes(`${createHash('sha256').update(name).digest('hex')}  ${name}\n`));
  writeFileSync(path.join(directory, names[0]), '');
  assert.throws(() => checksumInstallers(directory, '1.2.3'), /Empty installer/);
  writeFileSync(path.join(directory, 'wrong-version.exe'), 'unexpected');
  assert.throws(() => checksumInstallers(directory, '1.2.3'), /exactly the three/);
  assert.throws(() => installerNames('1.2.3-rc.1'), /stable release version/);
});

test('release commit and bundle preserve the exact source and reject extra changes', (t) => {
  const directory = mkdtempSync(path.join(os.tmpdir(), 'skarix-commit-'));
  t.after(() => rmSync(directory, { recursive: true, force: true }));
  const run = (...args) =>
    execFileSync('git', args, {
      cwd: directory,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    }).trim();
  run('init');
  run('config', 'user.name', 'Release test');
  run('config', 'user.email', 'test@example.com');
  writeFileSync(path.join(directory, 'base.txt'), 'source');
  run('add', '.');
  run('commit', '-m', 'fix: base');
  const base = run('rev-parse', 'HEAD');
  const version = '1.2.3';
  for (const file of ['package.json', 'package-lock.json'])
    writeFileSync(path.join(directory, file), JSON.stringify({ version }));
  writeFileSync(
    path.join(directory, '.release-please-manifest.json'),
    JSON.stringify({ '.': version }),
  );
  writeFileSync(path.join(directory, 'CHANGELOG.md'), 'notes');
  run('add', '.');
  run('commit', '-m', 'chore(main): release 1.2.3');
  const metadata = { base, sha: run('rev-parse', 'HEAD'), version, tag: `v${version}` };
  const cwd = process.cwd();
  try {
    process.chdir(directory);
    assertReleaseTarget(metadata);
    assert.throws(() => assertReleaseTarget({ ...metadata, tag: 'v1.2.4' }), /mismatch/);
    run('bundle', 'create', 'release.bundle', `${base}..HEAD`);
    assert.match(run('bundle', 'list-heads', 'release.bundle'), new RegExp(`${metadata.sha} HEAD`));
    writeFileSync(path.join(directory, 'unexpected.txt'), 'extra');
    run('add', 'unexpected.txt');
    run('commit', '--amend', '--no-edit');
    assert.throws(
      () => assertReleaseTarget({ ...metadata, sha: run('rev-parse', 'HEAD') }),
      /Unexpected release commit files/,
    );
  } finally {
    process.chdir(cwd);
  }
});
